async function provision(job: Job) {
  const server = await loadServer(job);
  // Clear any stale failure reason from a previous attempt as this run starts, so
  // a successful retry doesn't leave the last error hanging around on the row.
  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null, provisioningStep: null } });
  // Best-effort, human-readable "what's happening right now" label for
  // <ProvisioningOverlay/> (lib/provisioning-step.ts) — written between the real,
  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
  // SSH reachability, and the game's own port opening). Never allowed to fail
  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
  // equivalent `step()`.
  const step = (label: string) =>
    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);

  if (SANDBOX) {
    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
    // resize/start, no OVH allocation, no cloud-init snippet write. `vmid` IS
    // still allocated for real (via `allocateSandboxVmid`, see its doc comment
    // in lib/ipam.ts) — this used to be the racy inline `990000 +
    // (await db.server.count())`, which handed two servers the identical vmid
    // whenever no other Server row was created between their two provisioning
    // runs (the common case: rows are inserted at checkout, well before the
    // PROVISION job runs), and the second `prisma.server.update()` below died
    // on the `vmid` unique constraint. Only for a fresh allocation — a retry
    // keeps whatever vmid a previous attempt already claimed, same rule the
    // real Proxmox path follows just below in the non-sandbox branch.
    const vmid = server.vmid ?? (await allocateSandboxVmid(server.id));
    const password = generatePassword();
    const ip = sandboxIp(vmid);
    await db.server.update({
      where: { id: server.id },
      data: { ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
    });
    await notify(
      server.userId,
      `Server ${server.hostname} is ready`,
      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
      `/dashboard/servers/${server.id}`
    );
    // Post-purchase review request (once per server, skipped if no profiles set).
    await sendReviewRequestForServer(server.id);
    return;
  }

  const { conn, row: nodeRow } = await nodeFor(server);
  const storage = server.plan.storageTier === "hdd"
    ? nodeRow?.storageHdd ?? "vmdata-hdd"
    : nodeRow?.storageNvme ?? "vmdata";

  // Pick a vmid that does NOT still own a previous tenant's backup archives.
  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
  // server's vzdump archives, so the id freed by a deletion comes back carrying
  // the old owner's backups — which every backup surface then attributes to the
  // new customer (listBackups/requestRestore key on vmid alone). See
  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
  // keeps the vmid already persisted on the row.
  // The primary's real backup-archive storage predates the storageHdd naming
  // convention (it's literally "backup", not "vmdata-hdd") — every node
  // onboarded since names its backup-content storage after storageHdd instead.
  // See archivedVmids' doc comment in lib/proxmox.ts for the full story.
  const backupStorage = nodeRow?.isPrimary ? "backup" : (nodeRow?.storageHdd ?? "backup");
  const vmid = server.vmid ?? (await allocateFreshVmid(conn, backupStorage));

  // The password must be generated ONCE per VM, not once per attempt. cloud-init's
  // cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
  // cipassword was baked into the FIRST boot's snippet and never re-applies on a
  // later config change unless the guest gets a brand-new instance-id. A retried
  // PROVISION (server.vmid already set = the clone below is skipped as
  // `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
  // again anyway and overwrite Server.rootPasswordEnc with a value the running VM
  // never saw — every later SSH from the platform (control panel, GAME_POWER,
  // mods, backups) then authenticated with a password that does not match
  // /etc/shadow on the guest, failing with "All configured authentication methods
  // failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
  // logins ever, until the guest's password was force-resynced via the QGA
  // set-user-password path). Reuse the already-stored password whenever this
  // server already has a vmid (meaning some earlier attempt may have already
  // cloned + booted it); only a truly first attempt mints a new one.
  const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();

  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
  // VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
  // on every plan unless the admin switches it off). Game servers: the customer must
  // explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
  // intent, so the global default must NOT override it (that was silently granting free IPs).
  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
  const { getSettingBool: _settingBool } = await import("../lib/settings");
  const isGame = !!server.gamePlanId;
  const wantDedicated = isGame
    ? server.wantsDedicatedIp
    : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
  if (wantDedicated && (await dedicatedIpProviderConfigured(nodeRow?.id))) {
    try {
      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
      // server's already-ASSIGNED IP rather than claiming a second pool IP.
      // nodeRow is THIS server's own node — a Hetzner-hosted server draws from
      // the Hetzner pool, not whichever pool happens to be configured (the bug
      // this replaces: the old `ovhConfigured()`-only gate had no node
      // awareness at all).
      dedicated = await allocateDedicatedIp(server.id, vmid, nodeRow?.id);
      if (!dedicated) {
        // allocateDedicatedIp returns null (not a throw) when the node's pool has

