export async function placeGameOrder(
  user: User,
  intent: GameOrderIntent,
  sold?: GameOrderPrice | null,
  /** CARD path only: the hold `payAndDeployGame` reserved before the card was
   *  charged (see reserveOrderCoupon), confirmed here — RESERVED→CONSUMED —
   *  inside the same tx that commits the order. Mirrors lib/order.ts
   *  placeOrder's `opts.couponReservationToken` exactly. */
  couponReservationToken?: string | null,
): Promise<string> {
  const quote = await gameOrderQuote(intent);

  // CS2 needs a Steam Game Server Login Token to register with matchmaking at
  // all (SRCDS_TOKEN, no longer a required checkout field as of 2026-09-17 —
  // see lib/game-config.ts's field comment). Mint one automatically, ONCE,
  // here at actual order placement — never in gameOrderQuote, which the
  // wizard calls on every keystroke for a live price preview and would burn
  // through Valve's 1000-account-per-key budget on customers who never buy.
  // A customer who pasted their own token is left alone; a Steam API hiccup
  // degrades to "no token yet" (server still deploys and runs, just isn't
  // listed on matchmaking until one is added from the dashboard) rather than
  // failing the whole paid order over it.
  if (quote.gameFamily === "cs2" && !quote.values.SRCDS_TOKEN && steamGsltConfigured()) {
    try {
      const account = await createGameServerAccount(730, `nxeon:${quote.hostname}`);
      quote.values.SRCDS_TOKEN = account.loginToken;
      quote.values._SRCDS_TOKEN_STEAMID = account.steamid;
    } catch (e) {
      console.error(`[game-order] Steam GSLT auto-generation failed for ${quote.hostname}`, e);
    }
  }

  // Bill off the SOLD price when present (never re-priced after the card cleared),
  // else the fresh quote (which already folds in any valid coupon discount) —
  // this scalar is the whole truth about what this order costs.
  const chargeCents = sold?.chargeCents ?? quote.chargeCents;

  // Oversell guard — the VPS order path enforces this; game orders must too, or a
  // game server could commit host RAM past capacity.
  const capacity = await capacityCheck(quote.basePlanId);
  if (!capacity.ok) {
    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
  }

  // Pick a node the same way a VPS order does — without this, every game
  // server's `nodeId` stays null and `worker/index.ts`'s `nodeFor()` fallback
  // (`server.node ?? primary node`) pins EVERY game server onto the primary
  // node forever, regardless of its actual load. Confirmed live: every game
  // server in production had nodeId: null and primary sat at 84% real RAM /
  // 200% committed CPU while other nodes were comparatively idle.
  //
  // Region-aware exactly like lib/order.ts placeOrder: a customer picks a
  // REGION, not a specific node, so it is resolved fresh here (least loaded
  // within that region) rather than trusting whatever node the wizard's
  // local preview happened to resolve at page-load time.
  const node = intent.region
    ? await scheduleNode(quote.ramMB, { region: intent.region, provider: intent.provider })
    : await scheduleNode(quote.ramMB);
  if (intent.region && !node) {
    throw new GameOrderError("That location is at capacity right now — please pick another.");
  }

  // WALLET path: claim the coupon atomically BEFORE the balance gate/order tx,
  // so a wallet order fails cleanly (no money moved) if the code's last slot just
  // went, or this person already used it. Mirrors lib/order.ts placeOrder's own
  // wallet-path claim exactly (same shared claimOrderCoupon — one redemption
  // ledger for both VPS and game orders, not two).
  //
  // CARD path: does NOT claim here — `sold` means the card already charged the
  // discounted price, so a fresh claim now would double-count against the cap.
  // Real per-person enforcement for the card leg happens BEFORE the charge, via
  // `payAndDeployGame`'s reserveOrderCoupon hold (mirroring VPS's cardPromoToken);
  // this function only CONFIRMS that pre-existing hold below, inside the same tx
  // that commits the order — see confirmOrderCouponReservation's call site further
  // down. Added 2026-09-23 after a real gap: this path used to not gate the card
  // leg on any per-person limit at all, which the trial promo (a strictly
  // one-per-person, excludeActiveCustomers coupon) needed and didn't have.
  if (!sold && quote.couponId && quote.couponDiscountCents > 0) {
    try {
      await claimOrderCoupon({
        couponId: quote.couponId,
        maxRedemptions: quote.couponMaxRedemptions,
        firstTimeOnly: quote.couponFirstTimeOnly,
        excludeActiveCustomers: quote.couponExcludeActiveCustomers,
        userId: user.id,
        ipHash: null,
        amountCents: quote.couponDiscountCents,
      });
    } catch (e) {
      // claimOrderCoupon throws OrderError — translate to GameOrderError so
      // callers that only catch GameOrderError (payAndDeployGame, orderGameServer)
      // still surface this as a friendly inline message instead of an uncaught
      // exception / generic error page.
      throw new GameOrderError(e instanceof Error ? e.message : "That code couldn't be applied.");
    }
  }

  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
  // path the wallet was credited the card leg first, so this holds.
  if (user.balanceCents < chargeCents) {
    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
  }

  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
  const termLabel =
    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;

  // Line-item description shared by the wallet-transaction memo and the invoice —
  // mirrors lib/order.ts's VPS line ("<plan> VPS (<hostname>) — <term>"), the
  // pattern lib/actions-hosting.ts and lib/actions-email-hosting.ts also follow.
  const invDesc = `${quote.planName} Game Server (${quote.hostname}) — ${termLabel}`;

  let server;
  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
  // null and emails nothing. Mirrors `orderInvoice` in lib/order.ts placeOrder.
  let orderInvoice: { id: string; number: number; amountCents: number } | null = null;
  try {
    server = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
        },
      });
      // Billing document for the charge — created inside the same debit tx so it
      // shares the transaction's atomicity (a rolled-back charge leaves no invoice),
      // exactly like lib/order.ts's VPS invoice and worker/billing.ts's renewal
      // invoice. Game has no VAT, and any coupon discount is already netted into
      // `chargeCents`, so this is still a single line for the (already net) charge.
      const createdInvoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: invDesc,
          status: "PAID",
          taxCents: 0,
          taxRatePercent: 0,
          taxCountry: null,
          // A trial coupon's invoice should say what it actually billed for —
          // 7 days, not a month it didn't charge for.
          period: {
            start: new Date(),
            end: quote.couponTrialDays ? addDays(new Date(), quote.couponTrialDays) : addMonths(new Date(), quote.term),

          end: quote.couponTrialDays ? addDays(new Date(), quote.couponTrialDays) : addMonths(new Date(), quote.term),
        },
        lineItems: [{ description: invDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
      }),
    });
    orderInvoice = {
      id: createdInvoice.id,
      number: createdInvoice.number,
      amountCents: createdInvoice.amountCents,
    };
    // CARD/Stripe path: confirm the coupon hold reserved before the card was
    // charged (RESERVED→CONSUMED), inside this tx so the discount's slot
    // commits with the provision. NEVER a fresh claim — that would
    // re-increment the cap and collide on the per-person unique. `sold`
    // already carries the discounted total the customer paid, so no debit
    // changes here. Mirrors lib/order.ts placeOrder's identical step.
    if (sold && couponReservationToken) {
      const confirmed = await confirmOrderCouponReservation(tx, couponReservationToken);
      if (!confirmed) {
        // The hold is gone (released/swept) but the card already settled the
        // discounted leg. Keep the discounted charge (never overcharge past
        // what was shown) and log — same swallow discipline the VPS path uses.
        console.error(`[game-order] coupon hold ${couponReservationToken} vanished before confirm for paid order ${user.id}; kept sold price`);
      }
    }
    const s = await tx.server.create({
      // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
      // on Server until regenerated at deploy (see lib/order.ts's Server create).
      data: {
        name: quote.hostname,
        hostname: quote.hostname,
        label: quote.label,
        userId: user.id,
        planId: quote.basePlanId,
        gamePlanId: quote.gamePlanId,
        osTemplateId: quote.osTemplateId,
        // The customer's per-game setup, applied at the point of sale — the worker
        // renders these into the game's own config at provision (worker/game-config).
        gameVariant: quote.variant || null,
        subdomain: quote.subdomain,
        gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
        // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
        // game branch renews monthlyCents × termMonths × (1 − annual).
        termMonths: quote.term,
        // The rate this term was actually sold at, relative to the regular
        // price — 0 for every plan with no intro price (which is every
        // plan until an admin sets one), so this is exactly the old
        // hardcoded 0% for the common case and only changes for a plan
        // genuinely sold below its regular rate.
        termPromoPercent: quote.introPercent,
        // The annual rate frozen at sale, so the renewal bills the SAME price the
        // order charged even if the admin retunes annual_discount_percent later.
        annualDiscountPct: quote.annualPct,
        // GRANDFATHER PROGRAM: the game plan's raw priceCents AT THE
        // MOMENT OF SALE, frozen so a later catalog price rise never
        // touches this server's renewal — see Server.grandfatheredRenewalCents's
        // own doc comment and renewal-charge.ts. Deliberately the raw
        // per-term-unit catalog rate, NOT `regularPlanCents` (this ORDER's
        // term total) — renewalCharge divides this by gamePlan.termMonths
        // itself, same as it does for the live gamePlan.priceCents.
        grandfatheredRenewalCents: quote.gamePlanPriceCents,
        nodeId: node?.id ?? null,
        wantsDedicatedIp: quote.dedicatedIp,
        // See lib/order.ts's identical VPS-side comment: a trial coupon
        // shortens only this first period; grandfatheredRenewalCents above
        // is already the plan's real regular rate, so the next renewal
        // (in `couponTrialDays` days, not a month) bills full price with
        // no renewal-cron change.
        expiresAt: quote.couponTrialDays ? addDays(new Date(), quote.couponTrialDays) : addMonths(new Date(), quote.term),
      } as Prisma.ServerUncheckedCreateInput,
    });
    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
    return s;
  });
} catch (e) {
  if (e instanceof InsufficientBalanceError) {
    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
  }
  // Narrow race: another order claimed the same subdomain between the
  // isSubdomainAvailable check above and this insert (or the free tier just
  // claimed the same name in the other table's own concurrent request).
  if ((e as { code?: string })?.code === "P2002") {
    throw new GameOrderError("That subdomain was just taken — go back and pick another.");
  }
  throw e;
}

await db.auditLog.create({
  data: {
    userId: user.id,
    action: "gameserver.order",
    detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
  },
});
// Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
// place a game order is created & paid, reached by BOTH the wallet path
// (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts webhook /
// redirect), so every completed game deploy is counted once with a reliable userId.
// Terminal event (drives the completed counts, not a wizard-step row); best-effort
// and double-guarded so it can never disturb the money path.
try {
  await recordDeployFunnelComplete({ product: "game", step: "Complete", stepIndex: 5, userId: user.id });
} catch {
  /* never let funnel bookkeeping affect a completed order */
}
// Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
// the money has already moved, so a mail failure must NEVER surface as an order
// failure. Fires exactly once per order (single commit) and covers BOTH the wallet
// path (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts)
// because both go through this one placeGameOrder — mirrors lib/order.ts placeOrder
// and lib/actions-email-hosting.ts orderEmailHostingCore. Read via the declared
// union — the value is assigned inside the $transaction callback, which TS
// control-flow analysis does not track, so a direct read would narrow to `null`.
const invForEmail = orderInvoice as { id: string; number: number; amountCents: number } | null;
if (invForEmail) {
  try {
    const { sendMail, emails } = await import("./mailer");
    const branding = await invoiceBranding();
    const tpl = emails.invoiceNew(
      {
        invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
        amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
        dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
        description: invDesc,
      },
      true, // the itemised PDF is attached (invoiceId passed below)
    );
    await sendMail({
      to: user.email,
      subject: tpl.subject,
      html: tpl.html,
      template: tpl.template,
      invoiceId: invForEmail.id,
      userId: user.id,
      kind: "invoice",
    });
  } catch {
    /* invoice email is best-effort — a placed order must never fail on mail */
  }
}
return server.id;

