import { placeGameOrder } from "/opt/nxeon-staging/lib/game-order";

async function main() {
  const gamePlanId = process.argv[2];
  const configJson = process.argv[3];
  const hostname = process.argv[4];
  const config = configJson ? JSON.parse(configJson) : undefined;

  const email = "envkeyfix-test@nxeon.internal";
  const user = await db.user.upsert({
    where: { email },
    update: { balanceCents: 100000000 },
    create: {
      email,
      passwordHash: "x-not-a-real-login-envkeyfix-test",
      name: "EnvKeyFix Test",
      balanceCents: 100000000,
      excludeFromRevenue: true,
      role: "CUSTOMER",
    },
  });

  const serverId = await placeGameOrder(user, {
    gamePlanId,
    termMonths: 1,
    hostname,
    config,
  });
  console.log("SERVER_ID=" + serverId);
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

